def cantor_numbering(N: int) -> str:
    period = 1
    rank = 1
    digit = 0
    while True:
        j = sum(1 for _ in range(rank))
        if N == j:
            numerator = product(pow(3, k) * digit + 1
                               for k in range(rank))
            denominator = product(pow(3, k)
                                 for k in range(rank))
            break
        else:
            period = 2 * period + 1
            if N == j + period:
                numerator = numerator * 2
                denominator = denominator * 2
                break
            else:
                rank += 1
                digit = 1 - digit
                if rank == 3:
                    rank = 1
                    period = period * 2
                    digit = 0
                else:
                    digit = -digit
    return str(numerator) + '/' + str(denominator)

def max_product(num_str, N, K):
    if not num_str or N < 1 or K < 0:
        raise ValueError("Invalid input")
    if K > N - 1:
        raise ValueError("K must be less than the number of digits in the number string")
    if K == 0:
        return int(num_str)
    if K == N - 1:
        return int(num_str) * int(num_str[-1])
    max_prod = 0
    for i in range(N - 1):
        left = num_str[:i]
        right = num_str[i+1:]
        prod = int(left) * int(right)
        if prod > max_prod:
            max_prod = prod
    return max_prod

