        return isbn

    checksum = 0
    for i, c in enumerate(isbn):
        if i % 2 == 0:
            checksum += find_digit(c)
        else:
            checksum += int(c) * 3

    checksum = 10 - (checksum % 10)
    if checksum == 10:
        checksum = 0

    if isbn[-1].isdigit():
        if int(isbn[-1]) == checksum:
            return "Right"
        else:
            return isbn[:-1] + str(checksum)
    else:
        if isbn[-1].isupper():
            return isbn.lower() + str(checksum)
        else:
            return isbn

def find_digit(char: str) -> int:
    if char.isdigit():
        return int(char)
    else:
        return ord(char) - ord('a') + 10

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
