    for i in range(M):
        # Iterate over each vertical aisle
        for j in range(N):
            # Count the number of chatting pairs that can be separated by adding an aisle in the current position
            count = 0
            for pair in chatting_pairs:
                if (i+1, j+1) not in pair:
                    count += 1

            # Store the count in the aisle dictionary
            aisle_dict[(i, j)] = count

    # Select the most effective positions for aisles, aiming to separate as many chatting pairs as possible
    optimal_positions = sorted(aisle_dict, key=aisle_dict.get, reverse=True)[:K+L]

