def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Examples:

        >>> polynomial_to_string(5, [100, -1, 1, -3, 0, 10])
        '100x^5-x^4+x^3-3x^2+10'

        >>> polynomial_to_string(3, [-50, 0, 0, 1])
        '-50x^3+1'

    """
    if len(coeffs) != n + 1:
        raise ValueError(f"Coefficient length mismatch. Expected length: {n + 1}, Actual: {len(coeffs)}")

    terms = []
    for i in range(1, n+1):
        coeff = coeffs[n - i]
        if coeff != 0:
            term = ""
            if coeff > 0:
                term += "+"
            elif coeff < 0:
                term += "-"
            abs_coeff = abs(coeff)
            if abs_coeff != 1 or i == 1:
                term += str(abs_coeff)
            if i > 1:
                term += "x^" + str(i)
            terms.append(term)

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    decoded_message = ""
    mapping = build_letter_mapping(encoded, original)
    if mapping is None:
        return "Failed"
    for letter in message:
        if letter not in mapping:
            return "Failed"
        decoded_message += mapping[letter]
    return decoded_message

def build_letter_mapping(encoded: str, original: str) -> dict:
    mapping = {}
    for encoded_letter, original_letter in zip(encoded, original):
        if original_letter not in mapping:
            mapping[original_letter] = encoded_letter
        elif mapping[original_letter] != encoded_letter:
            return None
    return mapping

def count_partitions(n, k, x):
    if k == 1:
        return 1
    if n < x or k > n:
        return 0
    return sum(count_partitions(n-i, k-1, x) for i in range(x, n+1))

def count_sequences(n, last, memo):
    if n == last:
        return 1
    if last not in memo:
        memo[last] = sum(count_sequences(n, i, memo) for i in range(1, last // 2 + 1))
    return memo[last]

