def is_prime(num: int) -> bool:
    """
    Determine whether an integer is a prime number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules):
    visited = set()
    queue = deque([n])
    count = 0
    while queue:
        num = queue.popleft()
        if num not in visited:
            visited.add(num)
            count += 1
        for rule in rules:
            if str(rule[0]) in str(num):
                queue.append(num.replace(str(rule[0]), str(rule[1])))
    return count

