def min_remaining_space(V, n, volumes):
    # Initialize the dp array by setting all elements to 0
    dp = [0] * (n + 1)

    # Loop through all items and calculate the maximum volume that
    # can be occupied by any subset of the items up to that index
    for i in range(1, n + 1):
        max_volume = 0
        for j in range(i):
            if volumes[j] + dp[i - j] <= V:
                max_volume = max(max_volume, volumes[j] + dp[i - j])
        dp[i] = max_volume

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n]

