def minimum_students_to_leave(heights):
    if len(heights) <= 1:
        return 0
    heights.sort(reverse=True)
    left, right = 0, len(heights) - 1
    choir_formation = []
    while left < right:
        if heights[left] > heights[right]:
            choir_formation.append(heights[left])
            left += 1
        else:
            choir_formation.append(heights[right])
            right -= 1
    choir_formation.reverse()
    return len(heights) - len(choir_formation)

def hanoi_double_iterative(n: int) -> int:
    if n < 0:
        raise ValueError("Input n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 2
    result = 0
    for i in range(n - 1, 0, -1):
        result += pow(2, i)
    return result
